test("ファイルの名前はパスの末尾になる", () => {
  expect(FilePath.fileName(filePath("/work/settings-ui/app.dcmp"))).toBe(
    "app.dcmp",
  );
});

test("親フォルダの名前はパスの末尾から 2 番目になる", () => {
  expect(
    FilePath.folderName(filePath("/work/settings-ui/app.dcmp")),
  ).toStrictEqual(Option.some("settings-ui"));
});

test("Windows の区切りでもファイルの名前が取れる", () => {
  expect(FilePath.fileName(filePath("C:\\work\\settings-ui\\app.dcmp"))).toBe(
    "app.dcmp",
  );
});

test("Windows の区切りでも親フォルダの名前が取れる", () => {
  expect(
    FilePath.folderName(filePath("C:\\work\\settings-ui\\app.dcmp")),
  ).toStrictEqual(Option.some("settings-ui"));
});

test("ファイル名の要素を持つ文字列は、綴りを変えずにファイルのパスになる", () => {
  expect(FilePath.create("/work//settings-ui/./app.dcmp")).toStrictEqual(
    Option.some("/work//settings-ui/./app.dcmp"),
  );
});

test("区切りを含まないパスには親フォルダの名前が無い", () => {
  expect(FilePath.folderName(filePath("app.dcmp"))).toStrictEqual(Option.none);
});

test("ルート直下のファイルには親フォルダの名前が無い", () => {
  expect(FilePath.folderName(filePath("/app.dcmp"))).toStrictEqual(Option.none);
});

test("区切りが連続していても親フォルダの名前が取れる", () => {
  expect(FilePath.folderName(filePath("/work//app.dcmp"))).toStrictEqual(
    Option.some("work"),
  );
});

test("Windows のドライブ直下ではドライブ名が親フォルダの名前になる", () => {
  expect(FilePath.folderName(filePath("C:\\app.dcmp"))).toStrictEqual(
    Option.some("C:"),
  );
});

test.each([
  "",
  "/",
  "\\",
  "//",
])("ファイル名の要素を持たない文字列（%j）はファイルのパスにならない", (raw) => {
  expect(FilePath.create(raw)).toStrictEqual(Option.none);
});

test("区切りで終わっても空でない要素があればファイルのパスになり、その要素がファイル名になる", () => {
  expect(FilePath.fileName(filePath("/work/app/"))).toBe("app");
});

test("素の文字列はファイルのパスとして渡せない", () => {
  expectTypeOf<string>().not.toExtend<FilePath>();
});

test("ファイル名の取得は不在を返さない", () => {
  expectTypeOf(FilePath.fileName).returns.toEqualTypeOf<string>();
});

test("開くダイアログがファイル名の要素を持たないパスを返すと失敗になる", async () => {
  const fake = DocumentDialogFake.create({
    open: DialogChoice.chosen("/"),
    save: DialogChoice.Canceled,
  });

  const chosen = await fake.dialog.chooseOpenPath();

  expect(Result.isOk(chosen)).toBe(false);
});

test("保存のダイアログがファイル名の要素を持たないパスを返すと、その旨と受け取ったパスが失敗に残る", async () => {
  const fake = DocumentDialogFake.create({
    open: DialogChoice.Canceled,
    save: DialogChoice.chosen("\\"),
  });

  const chosen = await fake.dialog.chooseSavePath();

  expect(chosen).toStrictEqual(
    Result.err({ message: "選ばれたパスがファイル名を持たない: \\" }),
  );
});

test("ファイル名の要素を持たないパスは、その 1 件だけ配られない", async () => {
  const fake = FileDropFake.create();
  const received: (readonly string[])[] = [];
  Result.unwrap(
    await fake.drop.subscribeDropped((paths) => {
      received.push(paths);
    }),
  );

  fake.dropFiles(["/", Path]);

  expect(received).toStrictEqual([[Path]]);
});

test("ファイル名の要素を持つパスが 1 件も残らないドロップは配られない", async () => {
  const fake = FileDropFake.create();
  const received: (readonly string[])[] = [];
  Result.unwrap(
    await fake.drop.subscribeDropped((paths) => {
      received.push(paths);
    }),
  );

  fake.dropFiles(["/", "\\"]);
  // 配られる側を 1 件混ぜる。配る処理ごと壊れていても通る、を防ぐ。
  fake.dropFiles([Path]);

  expect(received).toStrictEqual([[Path]]);
});

test("空の並びのドロップは配られない", async () => {
  const fake = FileDropFake.create();
  const received: (readonly string[])[] = [];
  Result.unwrap(
    await fake.drop.subscribeDropped((paths) => {
      received.push(paths);
    }),
  );

  fake.dropFiles([]);
  // 配られる側を 1 件混ぜる。配る処理ごと壊れていても通る、を防ぐ。
  fake.dropFiles([Path]);

  expect(received).toStrictEqual([[Path]]);
});

test("ファイル名の要素を持たないパスはその 1 件だけ落ち、残りは順序のまま読み取れる", () => {
  const parsed = AppStateJson.parse(
    '{"recentPaths":["/work/a.dcmp","/","/work/b.dcmp"]}',
  );

  expect(Result.unwrap(parsed).recentPaths).toStrictEqual([
    "/work/a.dcmp",
    "/work/b.dcmp",
  ]);
});

test("ファイル名の要素を持たないパスの変更通知は配られない", async () => {
  const events = SingleEventIpcFake.create("document-changed");
  const ipc = DocumentIpc.create(events.ipc);
  const received: DocumentChanged[] = [];
  Result.unwrap(
    await ipc.subscribeChanged((changed) => received.push(changed)),
  );

  events.deliver({ path: "/", content: "{}" });
  events.deliver({ path: Path, content: "{}" });

  expect(received).toStrictEqual([{ path: Path, content: "{}" }]);
});

test("保存先と中身を取り違えて渡すことはできない", () => {
  const ipc = DocumentIpcFake.create().ipc;

  // 呼ばずに型だけを見る。
  const swapped = () =>
    // @ts-expect-error 中身の文字列はファイルのパスとして渡せない
    ipc.save("{}", Path);

  expectTypeOf(swapped).toBeFunction();
});

test("保存された一覧の先頭がファイル名の要素を持たなければ、次のファイルが起動時に開かれる", async () => {
  const observer = renderDocumentSession(
    { [Path]: artboardContent("home") },
    NoDialogChoices,
    { storedAppState: `{"recentPaths":["/","${Path}"]}` },
  );

  await observer.settle();

  expect(DocumentSession.activePath(observer.session())).toStrictEqual(
    Option.some(Path),
  );
});

test("保存された一覧のうちファイル名の要素を持たないパスは一覧に並ばない", async () => {
  const observer = renderDocumentSession({}, NoDialogChoices, {
    storedAppState: `{"recentPaths":["/","${Path}"]}`,
  });

  await observer.settle();

  expect(observer.recentPaths()).toStrictEqual([Path]);
});

test("落としたパスにファイル名の要素を持たないものが混ざっても、残りが開かれる", async () => {
  const observer = renderDocumentSession(
    { [Path]: artboardContent("home") },
    { open: DialogChoice.Canceled, save: DialogChoice.Canceled },
  );

  await observer.dropFiles(["/", Path]);

  expect(openedPaths(observer.session())).toStrictEqual([Path]);
});

test("落としたパスにファイル名の要素を持たないものが混ざっても、失敗は残らない", async () => {
  const observer = renderDocumentSession(
    { [Path]: artboardContent("home") },
    { open: DialogChoice.Canceled, save: DialogChoice.Canceled },
  );

  await observer.dropFiles(["/", Path]);

  expect(DocumentSession.failure(observer.session())).toStrictEqual(
    Option.none,
  );
});

test("ダイアログがファイル名の要素を持たないパスを返すと、ファイルの選択の失敗が残る", async () => {
  const observer = renderDocumentSession(
    {},
    { open: DialogChoice.chosen("/"), save: DialogChoice.Canceled },
  );

  await observer.openDocument();

  expect(DocumentSession.failure(observer.session())).toStrictEqual(
    Option.some({
      kind: "dialog",
      error: { message: "選ばれたパスがファイル名を持たない: /" },
    }),
  );
});

test("ファイル名の要素を持たないパスだけを落としても、直前の失敗の表示は消えない", async () => {
  const observer = renderDocumentSession(
    {},
    { open: DialogChoice.chosen(Path), save: DialogChoice.Canceled },
  );
  await observer.openDocument();
  const failed = DocumentSession.failure(observer.session());

  await observer.dropFiles(["/"]);

  expect(DocumentSession.failure(observer.session())).toStrictEqual(failed);
});

