function toChosenPath(
  chosen: Option<string>,
): Result<Option<FilePath>, DocumentDialogError> {
  if (!Option.isSome(chosen)) {
    return Result.ok(Option.none);
  }
  const path = FilePath.create(chosen.value);
  return Option.isSome(path)
    ? Result.ok(path)
    : Result.err({
        message: `選ばれたパスがファイル名を持たない: ${chosen.value}`,
      });
}

function segments(path: string): readonly string[] {
  return path.split(Separator).filter((segment) => segment.length > 0);
}

/**
 * パスの末尾の要素。
 *
 * 要素が無ければ空文字になる。`create` はこれが空でないことを条件にするので、`FilePath` を
 * 受ける `fileName` からは空は返らない。
 *
 * @param path 末尾を知りたいパス
 * @returns 末尾の要素。要素が 1 つも無ければ空文字列
 */
function lastSegment(path: string): string {
  return segments(path).slice(-1).join("");
}

export const FilePath = {
  /**
   * 外から届いた文字列を、ファイルのパスとして受け入れる。
   *
   * @param raw ダイアログ・ドロップ・保存されている状態・変更通知から届いたパス
   * @returns 綴りを変えずにファイルのパスとしたもの。区切りしか無い・空のときは `none`
   */
  create(raw: string): Option<FilePath> {
    return lastSegment(raw).length > 0
      ? Option.some(raw as FilePath)
      : Option.none;
  },

  /**
   * 末尾のファイルの名前。
   *
   * @param path 名前を知りたいパス
   * @returns パスの末尾の要素
   */
  fileName(path: FilePath): string {
    // 末尾を `Option` で取って `Option.unwrap` で開けることはしない。本番のコードに例外の経路を置かないため。
    return lastSegment(path);
  },

/**
 * 外から届いた文字列を、ファイルのパスとして受け入れる。
 *
 * @param raw ダイアログ・ドロップ・保存されている状態・変更通知から届いたパス
 * @returns 綴りを変えずにファイルのパスとしたもの。区切りしか無い・空のときは `none`
 */
create(raw: string): Option<FilePath> {
  return lastSegment(raw).length > 0
    ? Option.some(raw as FilePath)
    : Option.none;
},

/**
 * 素の型と構造が同じでも、取り違えを型で弾けるようにするための目印付きの型。テンプレー
 * トリテラル型で構造を狭められない値に使う。
 *
 * 目印までこの型に書くと、ここから作った型がすべて同じ目印を共有してしまう。
 *
 * 値を作れるのは、その事実を実行時に成立させる `create` の中だけ（rules/coding.md「狭い
 * 型への `as` は…戻り値1箇所のみ」）。
 *
 * @example
 * declare const FontWeightBrand: unique symbol;
 * export type FontWeight = Brand<number, typeof FontWeightBrand>;
 *
 * export const FontWeight = {
 *   create(value: number): Option<FontWeight> {
 *     return NumberEx.isWithin(value, { min: 100, max: 900 })
 *       ? Option.some(value as FontWeight)
 *       : Option.none;
 *   },
 * } as const;
 */
export type Brand<T, Tag extends symbol> = T & { readonly __brand: Tag };

/** 値がある状態。 */
export type Some<T> = Readonly<{
  some: true;
  value: T;
}>;

/** 値が無い状態。 */
export type None = Readonly<{
  some: false;
}>;

/**
 * 値が無いことがありうる処理の戻り値（rules/coding.md「エラーと不在の表現」）。
 * `Option.isSome` で分岐すると、ある場合だけ `value` が読める。
 */
export type Option<T> = Some<T> | None;
